using System.Security.Cryptography;
using Jindan.Contracts;
namespace Jindan.Modules.Files;

// Local PNG preview only. CAD originals are never edited or launched in another app.
public sealed class CadPreviewWindow : Form
{
    readonly IWorkspaceServices _services; readonly DocumentContext _context; readonly AssetInfo _asset; readonly CancellationTokenSource _cancel = new();
    readonly Panel _viewport = new() { Dock = DockStyle.Fill, AutoScroll = true, BackColor = Color.FromArgb(17, 24, 39) };
    readonly PictureBox _picture = new() { SizeMode = PictureBoxSizeMode.Normal, Location = Point.Empty };
    readonly Label _status = new() { AutoSize = true, Text = "로컬 CAD 해석 준비 중" }; readonly Button _cancelButton = new() { Text = "취소", Name = "CadCancel", AutoSize = true };
    Image? _image; double _zoom = 1; bool _fit = true, _drag; Point _dragStart, _scrollStart;
    private CadPreviewWindow(IWorkspaceServices services, DocumentContext context, AssetInfo asset)
    {
        _services = services; _context = context with { ContextId = context.ContextId + ":cad:" + Guid.NewGuid().ToString("N") }; _asset = asset; Name = "CadPreviewWindow"; Text = "CAD 미리보기 · " + asset.OriginalName; Width = 1100; Height = 800; MinimumSize = new Size(450, 350); AutoScaleMode = AutoScaleMode.Dpi; StartPosition = FormStartPosition.CenterParent;
        var tools = new FlowLayoutPanel() { Dock = DockStyle.Top, AutoSize = true, Padding = new Padding(6), WrapContents = true }; Button button(string name, string label, Action click) { var b = new Button() { Name = name, Text = label, AutoSize = true }; b.Click += (_, _) => click(); tools.Controls.Add(b); return b; }
        button("CadFit", "창에 맞추기", () => { _fit = true; Fit(); }); button("CadActual", "100%", () => { _fit = false; SetZoom(1); }); button("CadZoomIn", "확대 +", () => { _fit = false; SetZoom(_zoom * 1.25); }); button("CadZoomOut", "축소 −", () => { _fit = false; SetZoom(_zoom / 1.25); }); _cancelButton.Click += (_, _) => _cancel.Cancel(); tools.Controls.Add(_cancelButton); tools.Controls.Add(_status); _viewport.Controls.Add(_picture); Controls.Add(_viewport); Controls.Add(tools);
        _viewport.Resize += (_, _) => { if (_fit) Fit(); }; _picture.MouseWheel += (_, e) => { _fit = false; SetZoom(_zoom * (e.Delta > 0 ? 1.2 : 1 / 1.2)); }; _viewport.MouseWheel += (_, e) => { if ((ModifierKeys & Keys.Control) != 0) { _fit = false; SetZoom(_zoom * (e.Delta > 0 ? 1.2 : 1 / 1.2)); } }; _picture.MouseEnter += (_, _) => _picture.Focus(); _picture.TabStop = true;
        _picture.MouseDown += (_, e) => { if (e.Button != MouseButtons.Left) return; _drag = true; _dragStart = Cursor.Position; _scrollStart = new(-_viewport.AutoScrollPosition.X, -_viewport.AutoScrollPosition.Y); _picture.Capture = true; _picture.Cursor = Cursors.Hand; }; _picture.MouseMove += (_, _) => { if (!_drag) return; var p = Cursor.Position; _viewport.AutoScrollPosition = new(Math.Max(0, _scrollStart.X - (p.X - _dragStart.X)), Math.Max(0, _scrollStart.Y - (p.Y - _dragStart.Y))); }; _picture.MouseUp += (_, _) => { _drag = false; _picture.Capture = false; _picture.Cursor = Cursors.Default; }; FormClosed += (_, _) => { _cancel.Cancel(); _services.Reports.Invalidate(_context.ContextId); };
    }
    public static async Task ShowAsync(IWorkspaceServices services, DocumentContext context, AssetInfo asset) { var view = new CadPreviewWindow(services, context, asset); view.Show(); await view.LoadPreviewAsync(); }
    async Task LoadPreviewAsync() { var token = _cancel.Token; try { if (_context.ProjectId is null) throw new InvalidOperationException("프로젝트를 선택하세요."); var current = await _services.Assets.GetAsync(_services.Actor, _asset.Id, token); if (current.Sha256 != _asset.Sha256 || current.Size > 64L * 1024 * 1024) throw new InvalidDataException("CAD 원본 버전 또는64MB 크기 제한을 확인하세요."); var reply = await _services.Reports.ExecuteAsync(_context, new ReportCommand("cadPreview", _context.ProjectId, current.StoredPath, current.Sha256, Parameters: new() { { "filename", current.OriginalName } }), new Progress<ReportProgress>(p => { if (!IsDisposed) _status.Text = p.Stage; }), token); token.ThrowIfCancellationRequested(); if (!reply.Ok) throw new InvalidOperationException("로컬 CAD 미리보기: " + reply.ErrorCode); var artifact = reply.Artifacts.SingleOrDefault(a => a.MediaType == "image/png") ?? throw new InvalidDataException("PNG 미리보기 결과가 없습니다."); if (artifact.Size > 16L * 1024 * 1024) throw new InvalidDataException("CAD 미리보기 크기 제한을 초과했습니다."); var bytes = await File.ReadAllBytesAsync(artifact.Path, token); if (Convert.ToHexStringLower(SHA256.HashData(bytes)) != artifact.Sha256 || bytes.Length < 24 || !bytes.AsSpan(0, 8).SequenceEqual(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 })) throw new InvalidDataException("PNG 미리보기 무결성을 확인할 수 없습니다."); int w = System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(16, 4)), h = System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(20, 4)); if (w is < 1 or > 1600 || h is < 1 or > 1600) throw new InvalidDataException("CAD 미리보기 픽셀 제한을 초과했습니다."); using var stream = new MemoryStream(bytes, false); using var decoded = Image.FromStream(stream); var bitmap = new Bitmap(decoded); if (IsDisposed || token.IsCancellationRequested) { bitmap.Dispose(); return; } _image = bitmap; _picture.Image = _image; _cancelButton.Enabled = false; Fit(); _status.Text = $"{w}×{h} · 원본 보존 · 휠 확대/마우스 끌기"; } catch (OperationCanceledException) { if (!IsDisposed) _status.Text = "미리보기를 취소했습니다."; } catch (Exception e) { if (!IsDisposed) _status.Text = e.Message; } finally { if (!IsDisposed) _cancelButton.Enabled = false; } }
    void Fit() { if (_image is null) return; SetZoom(Math.Min(Math.Max(1, _viewport.ClientSize.Width - 24) / (double)_image.Width, Math.Max(1, _viewport.ClientSize.Height - 24) / (double)_image.Height)); }
    void SetZoom(double value) { if (_image is null) return; _zoom = Math.Clamp(value, .05, 8); _picture.Size = new(Math.Max(1, (int)Math.Round(_image.Width * _zoom)), Math.Max(1, (int)Math.Round(_image.Height * _zoom))); _viewport.AutoScrollMinSize = _picture.Size; _picture.Image = _image; _picture.SizeMode = PictureBoxSizeMode.StretchImage; }
    protected override void Dispose(bool disposing) { if (disposing) { _cancel.Cancel(); _picture.Image = null; _image?.Dispose(); _cancel.Dispose(); } base.Dispose(disposing); }
}
